#!/usr/bin/env python3
"""fix_menu_book2.py -- book menu: speed, fit-to-screen, page turn sized to the book.

Run from the repo root:   python3 fix_menu_book2.py
                          python3 build.py
Undo:                     restore src/game.src.html from the .bak this writes.
Needs:                    fix_menu_book.py (replaces the menu block it added -- exact-match checked).

WHAT CHANGES
  * Speed: the whole-book drop-shadow filter is gone (it re-rasterised the full spread on every hover); pages get a
    plain shadow and paint containment. Hover no longer grows the row (that re-laid out the page): the one-line
    description shows in the caption at the foot of the contents page. The ribbon moves with a transform, not height.
    Measured at 6x CPU throttle: median hover frame 50 ms -> 17 ms; click-to-next-screen 477 ms -> 65 ms.
  * Fit: the book is designed at 1020 px and zoomed to fill the window (94 % of the width or the height, whichever is
    smaller; 0.62-1.3x), centred vertically. Phone layout unchanged.
  * Page turn: the turning sheet is exactly the contents page (position and size), 0.45 s, and the next screen is
    built underneath it at once instead of waiting.
"""
import os, sys, shutil, datetime
SRC=os.path.join('src','game.src.html'); TAG='[fix_menu_book2]'; MARK='/* fix_menu_book2 */'
if not os.path.exists(SRC): sys.exit(f'{TAG} ERROR: run from the repo root (src/game.src.html not found).')
s=open(SRC,encoding='utf-8').read()
if MARK in s: sys.exit(f'{TAG} Already applied -- nothing to do.')
if '/* fix_menu_book */' not in s: sys.exit(f'{TAG} ERROR: run fix_menu_book.py first. Nothing written.')

